import creditsMd from '../../../CREDITS.md?raw';

/**
 * CREDITS.md (generated by `npm run import-sprites`) as simple HTML for Settings → Credits.
 * Credits live only in Settings, never on the match HUD or the lobby screen.
 */
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);

const inline = (t: string) =>
  esc(t)
    .replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
    .replace(/&lt;(https?:[^&\s]+)&gt;/g, '<a href="$1" target="_blank" rel="noopener">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');

let cache = '';
export function creditsHtml(): string {
  if (cache) return cache;
  const out: string[] = [];
  let list = false;
  let table = false;
  for (const raw of creditsMd.split(/\r?\n/)) {
    const line = raw.trimEnd();
    const isItem = /^\s*- /.test(line);
    const isRow = line.startsWith('|');
    if (list && !isItem) {
      out.push('</ul>');
      list = false;
    }
    if (table && !isRow) {
      out.push('</table>');
      table = false;
    }
    if (!line || line.startsWith('>') || /^# /.test(line)) continue;
    const h = /^(#{2,4}) (.*)$/.exec(line);
    if (h) {
      const n = h[1]!.length + 1;
      out.push(`<h${n}>${inline(h[2]!)}</h${n}>`);
    } else if (isItem) {
      if (!list) out.push('<ul>');
      list = true;
      const depth = (line.match(/^\s*/)?.[0].length ?? 0) / 2;
      out.push(`<li style="margin-left:${depth}em">${inline(line.replace(/^\s*- /, ''))}</li>`);
    } else if (isRow) {
      if (/^\|[\s|:-]+\|$/.test(line)) continue;
      if (!table) out.push('<table>');
      table = true;
      out.push(`<tr>${line.slice(1, -1).split('|').map((c) => `<td>${inline(c.trim())}</td>`).join('')}</tr>`);
    } else out.push(`<p>${inline(line)}</p>`);
  }
  if (list) out.push('</ul>');
  if (table) out.push('</table>');
  return (cache = out.join(''));
}
